default boolean isCoolingDown(World world, ItemStack stack) {
		int lastCooldown = NBTHelper.getInt(stack, NBTConstants.NBT.LAST_COOLDOWN, 0);
		long lastCast = NBTHelper.getLong(stack, NBTConstants.NBT.LAST_CAST, 0);
		long currentCast = world.getTotalWorldTime();

		long sub = currentCast - lastCast;
		return sub <= lastCooldown;
	}

default void setCooldown(World world, @Nullable EntityPlayer player, @Nullable EnumHand hand, ItemStack stack, @Nonnull SpellData data) {
		int maxCooldown = 0;

		List<SpellRing> rings = SpellUtils.getAllSpellRings(stack);

		for (SpellRing ring : rings) {
			if (ring.isContinuous()) return;

			if (ring.getModule() != null && ring.getModule().getModuleClass() instanceof IOverrideCooldown) {

				maxCooldown = ring.getCooldownTime(world, data);
				break;
			}
			if (ring.getCooldownTime() > maxCooldown)
				maxCooldown = ring.getCooldownTime();
		}

		if (maxCooldown <= 0) return;

		if (player != null && hand != null) {
			player.stopActiveHand();
			player.swingArm(hand);
			if (!world.isRemote)
				if (hand == EnumHand.MAIN_HAND)
					PacketHandler.NETWORK.sendTo(new PacketSyncCooldown(true, false), (EntityPlayerMP) player);
				else PacketHandler.NETWORK.sendTo(new PacketSyncCooldown(false, true), (EntityPlayerMP) player);
		}

		NBTHelper.setInt(stack, NBTConstants.NBT.LAST_COOLDOWN, maxCooldown);
		NBTHelper.setLong(stack, NBTConstants.NBT.LAST_CAST, world.getTotalWorldTime());
	}

@Override
	public boolean itemInteractionForEntity(ItemStack stack, EntityPlayer playerIn, EntityLivingBase target, EnumHand hand) {
		if (playerIn.isSneaking()) return false;
		if (isCoolingDown(playerIn.world, stack)) return false;
		if (BaublesSupport.getItem(playerIn, ModItems.CREATIVE_HALO, ModItems.FAKE_HALO, ModItems.REAL_HALO).isEmpty())
			return false;
		if (requiresBowAction(stack)) return false;

		SpellData spell = new SpellData();
		spell.processEntity(playerIn, true);
		spell.processEntity(target, false);
		SpellUtils.runSpell(playerIn.world, stack, spell);

		setCooldown(playerIn.world, playerIn, hand, stack, spell);
		return true;
	}

@Nonnull
	@Override
	public EnumActionResult onItemUse(EntityPlayer player, World world, BlockPos pos, EnumHand hand, EnumFacing side, float par8, float par9, float par10) {
		ItemStack stack = player.getHeldItem(hand);
		if (player.isSneaking()) {
			for (SpellRing spellRing : SpellUtils.getAllSpellRings(stack)) {
				if ((spellRing.getModule() != null ? spellRing.getModule().getModuleClass() : null) instanceof IBlockSelectable) {
					if (player.world.isAirBlock(pos)) break;
					NBTHelper.setCompound(stack, "selected", NBTUtil.writeBlockState(new NBTTagCompound(), world.getBlockState(pos)));
					player.stopActiveHand();
					player.swingArm(hand);
					return EnumActionResult.PASS;
				}
			}
		}

		if (isCoolingDown(world, stack)) return EnumActionResult.PASS;
		if (requiresBowAction(stack)) return EnumActionResult.PASS;
		if (BaublesSupport.getItem(player, ModItems.CREATIVE_HALO, ModItems.FAKE_HALO, ModItems.REAL_HALO).isEmpty())
			return EnumActionResult.PASS;

		SpellData spell = new SpellData();
		spell.processEntity(player, true);
		spell.processBlock(pos, side, new Vec3d(pos).add(0.5, 0.5, 0.5));
		SpellUtils.runSpell(world, stack, spell);

		setCooldown(world, player, hand, stack, spell);

		return EnumActionResult.PASS;
	}

@Nonnull
	@Override
	public ActionResult<ItemStack> onItemRightClick(World world, EntityPlayer player, @Nonnull EnumHand hand) {
		ItemStack stack = player.getHeldItem(hand);

		if(PotionTimeSlow.timeScale(player) == 0) return new ActionResult<>(EnumActionResult.PASS, stack);

		if (player.isSneaking()) return new ActionResult<>(EnumActionResult.PASS, stack);

		boolean hasHalo = BaublesSupport.getItem(player, ModItems.CREATIVE_HALO, ModItems.FAKE_HALO, ModItems.REAL_HALO).isEmpty();
		if (isCoolingDown(world, stack) || hasHalo) {
			return new ActionResult<>(EnumActionResult.FAIL, stack);
		} else {
			if (requiresBowAction(stack))
				player.setActiveHand(hand);
			else {
				SpellData spell = new SpellData();
				spell.processEntity(player, true);
				SpellUtils.runSpell(world, stack, spell);

				setCooldown(world, player, hand, stack, spell);
			}
			return new ActionResult<>(EnumActionResult.PASS, stack);
		}
	}

public boolean playerHasMobCharm(Player player, MobCharmDefinition charmDefinition) {
			ResourceLocation registryName = charmDefinition.getRegistryName();

			if (lastCharmCacheTime != player.level().getGameTime()) {
				lastCharmCacheTime = player.level().getGameTime();
				charmsInInventoryCache.clear();
			}
			return charmsInInventoryCache.computeIfAbsent(player.getUUID(), u -> getCharmRegistryNames(player)).contains(registryName);
		}

protected Set<ResourceLocation> getCharmRegistryNames(Player player) {
			return PlayerInventoryProvider.get().getFromPlayerInventoryHandlers(player, (slotStack, set) -> {
				if (slotStack.isEmpty()) {
					return set;
				}
				if (slotStack.getItem() == ModItems.MOB_CHARM.get()) {
					set.add(getEntityEggRegistryName(slotStack));
				}
				if (slotStack.getItem() == ModItems.MOB_CHARM_BELT.get()) {
					set.addAll(ModItems.MOB_CHARM_BELT.get().getCharmRegistryNames(slotStack));
				}
				return set;
			}, set -> false, HashSet::new);
		}

private void onEntityTargetedEvent(LivingChangeTargetEvent event) {
		if (event.getEntity().level().isClientSide() || !(event.getNewAboutToBeSetTarget() instanceof Player player)
				|| event.getNewAboutToBeSetTarget() instanceof FakePlayer || !(event.getEntity() instanceof Mob entity)) {
			return;
		}

		MobCharmRegistry.getCharmDefinitionFor(entity).ifPresent(charmDefinition -> {
			if (isMobCharmPresent(player, charmDefinition)) {
				event.setCanceled(true);
			}
		});
	}

private void onLivingUpdate(EntityTickEvent.Pre event) {
		if (event.getEntity().level().isClientSide() || !(event.getEntity() instanceof Mob entity)) {
			return;
		}

		Player player = getRealPlayer(entity.getTarget()).orElse(null);
		if (player == null) {
			player = getRealPlayer(entity.getLastHurtByMob()).orElse(null);
		}
		if (player == null) {
			player = MobHelper.getTargetedPlayerFromMemory(entity).orElse(null);
		}

		if (player == null) {
			return;
		}

		Player finalPlayer = player;
		MobCharmRegistry.getCharmDefinitionFor(entity).ifPresent(charmDefinition -> {
			if (isMobCharmPresent(finalPlayer, charmDefinition)) {
				MobHelper.resetTarget(entity, true);
			}
		});
	}

private Optional<Player> getRealPlayer(@Nullable LivingEntity livingEntity) {
		return livingEntity instanceof Player p && !(livingEntity instanceof FakePlayer) ? Optional.of(p) : Optional.empty();
	}

@Override
	public void detonate() {
		PlayerData playerData = PsiPlayerData.get(player);
		long worldTime = player.level().getGameTime();

		if(playerData.lastTriggeredDetonation != worldTime) {
			playerData.lastTriggeredDetonation = worldTime;
			PsiArmorEvent.post(new PsiArmorEvent(player, PsiArmorEvent.DETONATE));
		}
	}

@Override
	public Object execute(SpellContext context) throws SpellRuntimeException {
		double radiusVal = Math.min(MAX_DISTANCE, this.getNotNullParamValue(context, radius).doubleValue());

		if(radiusVal == 0.0) {
			IDetonationHandler.performDetonation(context.focalPoint.level(), context.caster, 0, entity -> entity == context.caster);
			return null;
		}
		IDetonationHandler.performDetonation(context.focalPoint.level(), context.caster, context.focalPoint, radiusVal);
		return null;
	}

static void performDetonation(Level world, Player player, Entity center, double range, Predicate<Entity> filter) {
		List<Entity> charges = world.getEntitiesOfClass(Entity.class,
				center.getBoundingBox().inflate(range),
				entity -> {
					if(entity == null) {
						return false;
					}
					IDetonationHandler detonator = PsiCapabilities.detonationHandler(entity);
					if(detonator != null) {
						Vec3 locus = detonator.objectLocus();
						if(locus == null || SpatialHelper.distanceSquared(world, locus, center.position()) > range * range) {
							return false;
						}
						return filter == null || filter.test(entity);
					}
					return false;
				});

		List<IDetonationHandler> handlers = charges.stream()
				.map(e -> Objects.requireNonNull(PsiCapabilities.detonationHandler(e)))
				.collect(Collectors.toList());

		if(!PsiEvents.post(new DetonationEvent(player, center, range, handlers)).isCanceled()) {
			if(!handlers.isEmpty()) {
				for(IDetonationHandler handler : handlers) {
					handler.detonate();
				}
			}
		}
	}

public static void tick(AbstractArrow arrow) {
        if (!arrow.isNoGravity()) {
            arrow.removeData(Attachments.ANTI_GRAVITY_ARROW_START);
            return;
        }

        long start = arrow.getData(Attachments.ANTI_GRAVITY_ARROW_START);
        boolean spent = arrow.getDeltaMovement().lengthSqr() < SPENT_SPEED_SQ;
        boolean expired = arrow.level().getGameTime() - start >= MAX_FLIGHT_TICKS;
        if (spent || expired) {
            restoreGravity(arrow);
        }
    }

@Override
    public void onProjectileFired(GemInstance inst, LivingEntity user, Projectile proj) {
        if (proj instanceof AbstractArrow arrow) {
            arrow.setNoGravity(true);
            arrow.setData(Attachments.ANTI_GRAVITY_ARROW_START, user.level().getGameTime());
        }
    }

@Override
    public void onProjectileImpact(GemInstance inst, Projectile proj, HitResult res) {
        if (proj instanceof AbstractArrow arrow) {
            restoreGravity(arrow);
        }
    }

public static void restoreGravity(AbstractArrow arrow) {
        arrow.setNoGravity(false);
        arrow.removeData(Attachments.ANTI_GRAVITY_ARROW_START);
    }

@SubscribeEvent
    @SuppressWarnings("deprecation")
    public void update(EntityTickEvent.Post e) {
        Entity entity = e.getEntity();
        if (entity instanceof AbstractArrow arrow && !arrow.level().isClientSide() && arrow.hasData(Attachments.ANTI_GRAVITY_ARROW_START)) {
            AntiGravityArrowBonus.tick(arrow);
        }
        if (entity.getPersistentData().contains("apoth.burns_in_sun")) {
            // Copy of Mob#isSunBurnTick()
            if (entity.level().isBrightOutside() && !entity.level().isClientSide()) {
                float f = entity.getLightLevelDependentMagicValue();
                BlockPos blockpos = BlockPos.containing(entity.getX(), entity.getEyeY(), entity.getZ());
                boolean flag = entity.isInWaterOrRain() || entity.isInPowderSnow || entity.wasInPowderSnow;
                if (f > 0.5F && entity.getRandom().nextFloat() * 30.0F < (f - 0.4F) * 2.0F && !flag && entity.level().canSeeSky(blockpos)) {
                    entity.setRemainingFireTicks(160);
                }
            }
        }
    }

@Override
	public boolean hurt(DamageSource source, float amount) {
		boolean hurt = super.hurt(source, amount);
		if (source.is(DamageTypes.ON_FIRE) || source.is(DamageTypes.FALL) || source.is(DamageTypes.DROWN) || source.is(DamageTypes.FIREBALL) || source.is(DamageTypes.UNATTRIBUTED_FIREBALL) || source.is(DamageTypes.SWEET_BERRY_BUSH) || source.is(DamageTypes.CACTUS) || source.is(DamageTypes.FALLING_ANVIL) || source.is(DamageTypes.FALLING_BLOCK) || source.is(DamageTypes.FALLING_STALACTITE) || source.is(DamageTypes.FREEZE) || source.is(DamageTypes.HOT_FLOOR) || source.is(DamageTypes.IN_FIRE) || source.is(DamageTypes.IN_WALL) || source.is(DamageTypes.LAVA) || source.is(DamageTypes.LIGHTNING_BOLT) || source.is(DamageTypes.MAGIC) || source.is(DamageTypes.STALAGMITE)) {
			return false;
		} else {
			if (hurt && !this.level().isClientSide && source.getEntity() instanceof Player) {
				long time = this.level().getGameTime();
				this.recentHitTicks.addLast(time);
				this.pruneOldHits(time);
			}
			return hurt;
		}
	}

private void pruneOldHits(long now) {
		while (!this.recentHitTicks.isEmpty() && now - this.recentHitTicks.peekFirst() > 200) {
			this.recentHitTicks.pollFirst();
		}
	}

public boolean wasHitFrequently() {
		this.pruneOldHits(this.level().getGameTime());
		return this.recentHitTicks.size() >= 4;
	}

public void clearRecentHits() {
		this.recentHitTicks.clear();
	}

@Override
		public boolean canUse() {
			if (cooldown > 0) {
				cooldown--;
				return false;
			}
			LivingEntity target = pyrinos.getTarget();
			return target != null && target.isAlive() && pyrinos.distanceToSqr(target) <= 9.0D
					&& pyrinos.wasHitFrequently();
		}

@Override
		public void start() {
			triggered = false;
			animationTicks = 0;
			pyrinos.setFlappingWings(true);
		}

@Override
		public void tick() {
			animationTicks++;

			LivingEntity target = pyrinos.getTarget();
			if (target == null) return;

			if (!triggered) {
				Vec3 push = target.position().subtract(pyrinos.position()).normalize().scale(2.2D);
				target.setDeltaMovement(push.x, 0.4D, push.z);
				target.hurtMarked = true;

				pyrinos.clearRecentHits();
				triggered = true;
			}
		}

@Override
		public void stop() {
			cooldown = 60;
			pyrinos.setFlappingWings(false);
		}

public boolean passIn(ItemStack stack, Direction face, Direction backlog, long seed, int time) {
		PipeItem item = new PipeItem(stack, face, seed);
		item.lastTickUpdated = level.getGameTime();
		item.backloggedFace = backlog;
		if(!iterating) {
			int currentOut = getComparatorOutput();
			pipeItems.add(item);
			item.timeInWorld = time;
			if(getComparatorOutput() != currentOut)
				level.updateNeighbourForOutputSignal(getBlockPos(), getBlockState().getBlock());
		} else {
            queuedItems.add(item);
        }

		return true;
	}

public void tick() {
		//convert old pipes
		if(convert) {
			convert = false;
			refreshVisualConnections();
		}
		boolean enabled = isPipeEnabled();
		if(!enabled && level.getGameTime() % 10 == 0 && level instanceof ServerLevel serverLevel)
			serverLevel.sendParticles(new DustParticleOptions(new Vector3f(1.0F, 0.0F, 0.0F), 1.0F), worldPosition.getX() + 0.5, worldPosition.getY() + 0.5, worldPosition.getZ() + 0.5, 3, 0.2, 0.2, 0.2, 0);

		BlockState blockAt = level.getBlockState(worldPosition);
		if(!level.isClientSide && enabled && blockAt.is(PipesModule.pipesTag)) {
			for(Direction side : Direction.values()) {
				if(connectionsCache[side.ordinal()] == ConnectionType.OPENING) {
					double minX = worldPosition.getX() + 0.25 + 0.5 * Math.min(0, side.getStepX());
					double minY = worldPosition.getY() + 0.25 + 0.5 * Math.min(0, side.getStepY());
					double minZ = worldPosition.getZ() + 0.25 + 0.5 * Math.min(0, side.getStepZ());
					double maxX = worldPosition.getX() + 0.75 + 0.5 * Math.max(0, side.getStepX());
					double maxY = worldPosition.getY() + 0.75 + 0.5 * Math.max(0, side.getStepY());
					double maxZ = worldPosition.getZ() + 0.75 + 0.5 * Math.max(0, side.getStepZ());

					Direction opposite = side.getOpposite();

					boolean pickedItemsUp = false;
					Predicate<ItemEntity> predicate = entity -> {
						if(entity == null || !entity.isAlive())
							return false;

						Vec3 motion = entity.getDeltaMovement();
						Direction dir = Direction.getNearest(motion.x, motion.y, motion.z);

						return dir == opposite;
					};

					for(ItemEntity item : level.getEntitiesOfClass(ItemEntity.class, new AABB(minX, minY, minZ, maxX, maxY, maxZ), predicate)) {
						passIn(item.getItem().copy(), side);

						if(PipesModule.doPipesWhoosh) {
							if(isTheGoodDay())
								level.playSound(null, item.getX(), item.getY(), item.getZ(), QuarkSounds.BLOCK_PIPE_PICKUP_LENNY, SoundSource.BLOCKS, 1f, 1f);
							else
								level.playSound(null, item.getX(), item.getY(), item.getZ(), QuarkSounds.BLOCK_PIPE_PICKUP, SoundSource.BLOCKS, 1f, 1f);
						}

						if(PipesModule.emitVibrations)
							getLevel().gameEvent(GameEvent.PROJECTILE_LAND, getBlockPos(), Context.of(getBlockState()));

						pickedItemsUp = true;
						item.discard();
					}

					if(pickedItemsUp)
						sync();
				}
			}
		}

		int currentOut = getComparatorOutput();

		if(!pipeItems.isEmpty()) {
			if(PipesModule.maxPipeItems > 0 && pipeItems.size() > PipesModule.maxPipeItems && !level.isClientSide) {
				level.levelEvent(LevelEvent.PARTICLES_DESTROY_BLOCK, worldPosition, Block.getId(level.getBlockState(worldPosition)));
				dropItem(new ItemStack(getBlockState().getBlock()));
				level.removeBlock(getBlockPos(), false);
			}

			ListIterator<PipeItem> itemItr = pipeItems.listIterator();
			iterating = true;
			while(itemItr.hasNext()) {
				PipeItem item = itemItr.next();
				Direction lastFacing = item.outgoingFace;
				if(item.tick(this)) {
					itemItr.remove();

					if(item.valid)
						passOut(item);
					else if(!level.isClientSide) {
						dropItem(item.stack, lastFacing, true);
					}
				}
			}
			iterating = false;

			if(!queuedItems.isEmpty()) {
				pipeItems.addAll(queuedItems);
				queuedItems.clear();
                sync();
            }
		}



		if(getComparatorOutput() != currentOut)
			level.updateNeighbourForOutputSignal(getBlockPos(), getBlockState().getBlock());
	}

protected void passOut(PipeItem item) {
		boolean did = false;

		BlockPos targetPos = getBlockPos().relative(item.outgoingFace);
		if(level.getBlockState(targetPos).getBlock() instanceof WorldlyContainerHolder) {
			ItemStack result = MiscUtil.putIntoInv(item.stack, level, targetPos, null, item.outgoingFace.getOpposite(), false, false);
			if(result.getCount() != item.stack.getCount()) {
				did = true;
				if(!result.isEmpty())
					bounceBack(item, result);
			}
		} else {
			BlockEntity tile = level.getBlockEntity(targetPos);
			if(tile != null) {
				if(tile instanceof PipeBlockEntity pipe)
					did = pipe.passIn(item.stack, item.outgoingFace.getOpposite(), null, item.rngSeed, item.timeInWorld);
				else if(!level.isClientSide) {
					ItemStack result = MiscUtil.putIntoInv(item.stack, level, targetPos, tile, item.outgoingFace.getOpposite(), false, false);
					if(result.getCount() != item.stack.getCount()) {
						did = true;
						if(!result.isEmpty())
							bounceBack(item, result);
					}
				}
			}
		}

		if(!did)
			bounceBack(item, null);
	}

private void bounceBack(PipeItem item, ItemStack stack) {
		if(!level.isClientSide) {
            passIn(stack == null ? item.stack : stack, item.outgoingFace, item.incomingFace, item.rngSeed, item.timeInWorld);
        }
	}

protected boolean tick(PipeBlockEntity pipe) {
			long gameTime = pipe.level.getGameTime();
			if(lastTickUpdated != gameTime) {
				lastTickUpdated = gameTime;

				ticksInPipe++;
				timeInWorld++;

				if(ticksInPipe == PipesModule.effectivePipeSpeed / 2 - 1) {
					outgoingFace = getTargetFace(pipe);
				}

				if(outgoingFace == null) {
					valid = false;
					return true;
				}
			}

			return ticksInPipe >= PipesModule.effectivePipeSpeed;
		}

protected Direction getTargetFace(PipeBlockEntity pipe) {
			BlockPos pipePos = pipe.getBlockPos();
			if(incomingFace != Direction.DOWN && backloggedFace != Direction.DOWN && pipe.canFit(stack, pipePos.relative(Direction.DOWN), Direction.UP))
				return Direction.DOWN;

			Direction incomingOpposite = incomingFace; // init as same so it doesn't break in the remove later
			if(incomingFace.getAxis() != Axis.Y) {
				incomingOpposite = incomingFace.getOpposite();
				if(incomingOpposite != backloggedFace && pipe.canFit(stack, pipePos.relative(incomingOpposite), incomingFace))
					return incomingOpposite;
			}

			List<Direction> sides = new ArrayList<>(HORIZONTAL_SIDES_LIST);
			sides.remove(incomingFace);
			sides.remove(incomingOpposite);

			Random rng = new Random(rngSeed);
			rngSeed = rng.nextLong();
			Collections.shuffle(sides, rng);
			for(Direction side : sides) {
				if(side != backloggedFace && pipe.canFit(stack, pipePos.relative(side), side.getOpposite()))
					return side;
			}

			if(incomingFace != Direction.UP && backloggedFace != Direction.UP && pipe.canFit(stack, pipePos.relative(Direction.UP), Direction.DOWN))
				return Direction.UP;

			if(backloggedFace != null)
				return backloggedFace;

			return null;
		}

@Override
  public void onInventoryTick(IToolStackView tool, ModifierEntry modifier, Level world, LivingEntity holder, int itemSlot, boolean isSelected, boolean isCorrectSlot, ItemStack stack) {
    // overslime increases every 2^(4-level) seconds
    // that is 1 per second at 4 levels, 1 per 8 seconds at 1 level
    // we support max level 6, as that leaves us working with integers
    int level = Math.min(modifier.getLevel(), 6);
    int updateInterval = 5 << (6 - level);

    // don't run if drawing back a bow, prevents losing animation
    // does mean you may end up wasting some fuel, could be as much as 19 lost. So, don't hold your bows for 20 updates?
    if (!world.isClientSide && holder.tickCount % updateInterval == 0 && holder.getUseItem() != stack) {
      // must have overslime and space to fill
      if (OverslimeModule.INSTANCE.getAmount(tool) < OverslimeModule.getCapacity(tool)) {
        // find current fuel info
        ResourceLocation key = modifier.getId();
        FuelInfo info = FuelInfo.read(tool, key);

        // if we have no fuel, try and find some
        boolean neededFuel = info == null;
        // since we will write this to NBT, use game time as that is global
        long time = holder.level().getGameTime();
        if (neededFuel || info.expiration < time) {
          info = null;
          FluidStack fluid = ToolTankHelper.TANK_HELPER.getFluid(tool);
          if (!fluid.isEmpty()) {
            MeltingFuel fuel = MeltingFuelLookup.findFuel(fluid.getFluid());
            if (fuel != null) {
              // scale amount consumed by level
              int amount = fuel.getAmount(fluid.getFluid());
              // scale up fuel duration so we always get the same amount of overslime per fuel bucket
              // if we didn't do this, lower levels would consume way more than higher ones
              // this works out to equivalent to the alloyer/melter at level 4
              // note this does mean changing trait levels multiplies fuel efficiency, but the part swap costs more than just adding a slimeball so its fine
              int duration = fuel.getDuration() * updateInterval / 5;
              // if we don't have a full recipe, use what is left but scale down the duration
              if (amount > fluid.getAmount()) {
                ToolTankHelper.TANK_HELPER.setFluid(tool, FluidStack.EMPTY);
                duration = duration * fluid.getAmount() / amount;
              } else {
                // if we have a complete recipe, just decrease fluid in the tank
                fluid.shrink(amount);
                ToolTankHelper.TANK_HELPER.setFluid(tool, fluid);
              }
              info = new FuelInfo(time + duration, fuel.getRate());
            }
          }
          // store current fuel in NBT for next round if it will last
          // no need to store if it will expire before our next update tick though
          if (info != null && info.expiration >= time + updateInterval) {
            info.write(tool, key);
          } else if (!neededFuel) {
            // no need to remove if we had nothing, saves some hash map modifications
            tool.getPersistentData().remove(key);
          }
        }
        // if we have fuel, increase overslime
        if (info != null) {
          // restore 1 per 10 rate. For the remainder, treat it as a chance
          int restore = info.rate / 10;
          int remainder = info.rate % 10;
          if (remainder > 0 && Modifier.RANDOM.nextInt(10) < remainder) {
            restore++;
          }
          OverslimeModule.INSTANCE.addAmount(tool, restore);
        }
      }
    }
  }

@Nullable
    public static FuelInfo read(IToolStackView tool, ResourceLocation location) {
      ModDataNBT persistentData = tool.getPersistentData();
      if (persistentData.contains(location, Tag.TAG_COMPOUND)) {
        CompoundTag tag = persistentData.getCompound(location);
        return new FuelInfo(tag.getLong(EXPIRATION), tag.getInt(RATE));
      }
      return null;
    }

public void write(IToolStackView tool, ResourceLocation location) {
      CompoundTag tag = new CompoundTag();
      tag.putLong(EXPIRATION, expiration);
      tag.putInt(RATE, rate);
      tool.getPersistentData().put(location, tag);
    }

@Nullable
  @Override
  public Component onRemoved(IToolStackView tool, Modifier modifier) {
    tool.getPersistentData().remove(modifier.getId());
    return null;
  }

@SubscribeEvent
        public static void onLivingHurt3(LivingDamageEvent.Pre event) {
            if (!(event.getSource().getEntity() instanceof LivingEntity attacker))
                return;

            var rings = EntityUtils.findEquippedCurios(attacker, RelicsItems.RING_OF_THE_SEVEN_DEADLY_SINS.get(), stack -> {
                var relic = (RingOfTheSevenDeadlySinsItem) stack.getItem();

                return relic.getRelicData(attacker, stack).getAbilitiesData().getAbilityData("wrath").canPlayerUse(attacker);
            });

            if (rings.isEmpty())
                return;

            var now = attacker.level().getGameTime();
            var baseDamage = event.getNewDamage();
            var totalModifier = 1D;
            var ringModifiers = new ArrayList<Double>(rings.size());

            for (var stack : rings) {
                var relic = (RingOfTheSevenDeadlySinsItem) stack.getItem();

                if (!TargetingUtils.canHarm(attacker, event.getEntity(), stack, "wrath")) {
                    ringModifiers.add(1D);
                    continue;
                }

                var windowTicks = Math.max(1, (int) Math.round(relic.getRelicData(attacker, stack).getAbilitiesData().getAbilityData("wrath").getStatData("window").getValue() * 20D));
                var state = stack.getOrDefault(RelicsDataComponents.RING_OF_THE_SEVEN_DEADLY_SINS_WRATH.get(), WrathData.create(now));
                var delta = now - state.lastHitTick();

                double modifier = 1D;

                if (delta < windowTicks) {
                    var mid = windowTicks / 2D;
                    var earlyMultiplier = relic.getRelicData(attacker, stack).getAbilitiesData().getAbilityData("wrath").getStatData("early_multiplier").getValue();
                    var lateMultiplier = relic.getRelicData(attacker, stack).getAbilitiesData().getAbilityData("wrath").getStatData("late_multiplier").getValue();

                    if (delta <= mid) {
                        var t = delta / mid;
                        var start = 1D + earlyMultiplier;

                        modifier = start + (1D - start) * t;
                    } else {
                        var t = (delta - mid) / Math.max(1D, windowTicks - mid);
                        var end = 1D - lateMultiplier;

                        modifier = 1D + (end - 1D) * t;
                    }
                }

                ringModifiers.add(modifier);
                totalModifier *= modifier;
            }

            event.setNewDamage((float) (baseDamage * totalModifier));

            for (var i = 0; i < rings.size(); i++) {
                var stack = rings.get(i);
                var relic = (RingOfTheSevenDeadlySinsItem) stack.getItem();
                var modifier = ringModifiers.get(i);
                var extraDamage = baseDamage * (modifier - 1D);

                relic.getRelicData(attacker, stack).getAbilitiesData().getAbilityData("wrath").getStatisticData().getMetricData("windows").addValue(1);
                relic.getRelicData(attacker, stack).getLevelingData().addExperience("wrath", "timing", Math.abs(extraDamage));

                if (extraDamage > 0)
                    relic.getRelicData(attacker, stack).getAbilitiesData().getAbilityData("wrath").getStatisticData().getMetricData("bonus_damage").addValue(extraDamage);
                else if (extraDamage < 0)
                    relic.getRelicData(attacker, stack).getAbilitiesData().getAbilityData("wrath").getStatisticData().getMetricData("reduced_damage").addValue(Math.abs(extraDamage));

                stack.set(RelicsDataComponents.RING_OF_THE_SEVEN_DEADLY_SINS_WRATH.get(), new WrathData(now));
            }
        }

public static WrathData create(long tick) {
            return new WrathData(tick);
        }
